import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["inp1__shape"])
    dtype = getattr(torch, ctx["inp1__dtype"])
    is_bool = (dtype == torch.bool) or (str(dtype) in ("torch.bool", "bool"))
    if is_bool:
        inp1 = torch.randint(0, 2, size=tuple(shape), dtype=torch.bool, device=device)
        inp2 = torch.randint(0, 2, size=tuple(shape), dtype=torch.bool, device=device)
    else:
        inp1 = torch.randint(
            low=-0x7FFF, high=0x7FFF, size=tuple(shape), dtype=dtype, device="cpu"
        ).to(device)
        inp2 = torch.randint(
            low=-0x7FFF, high=0x7FFF, size=tuple(shape), dtype=dtype, device="cpu"
        ).to(device)
    return {"inp1": inp1, "inp2": inp2}


def run(inp1, inp2):
    inp1 |= inp2
    return inp1
